INSERT INTO `wp_options` VALUES (516,'options_pengurus_list','a:6:{i:0;a:10:{s:4:\"nama\";s:20:\"DRS. H. Zarkasih Nur\";s:8:\"kategori\";s:22:\"Dewan Pengawas Syariah\";s:7:\"jabatan\";s:28:\"Ketua Dewan Pengawas Syariah\";s:4:\"foto\";s:91:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/pengurus/dps-ketua.png\";s:13:\"riwayat_karir\";s:220:\"Berpengalaman lebih dari 20 tahun di bidang ekonomi syariah dan fatwa keuangan Islam. Aktif sebagai narasumber di berbagai forum perbankan syariah nasional dan pelatihan sertifikasi DPS yang diselenggarakan oleh DSN-MUI.\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:44:\"Sertifikasi Dewan Pengawas Syariah (DSN-MUI)\";s:7:\"kutipan\";s:69:\"Menjaga kemurnian prinsip syariah adalah fondasi kepercayaan nasabah.\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:1;}i:1;a:10:{s:4:\"nama\";s:8:\"Haryanto\";s:8:\"kategori\";s:22:\"Dewan Pengawas Syariah\";s:7:\"jabatan\";s:30:\"Anggota Dewan Pengawas Syariah\";s:4:\"foto\";s:93:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/pengurus/dps-anggota.png\";s:13:\"riwayat_karir\";s:184:\"Memiliki keahlian mendalam dalam fikih muamalah dan hukum ekonomi syariah. Berkontribusi aktif dalam pengembangan produk-produk keuangan syariah yang inovatif dan sesuai fatwa DSN-MUI.\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:44:\"Sertifikasi Dewan Pengawas Syariah (DSN-MUI)\";s:7:\"kutipan\";s:69:\"Inovasi keuangan harus tetap berpijak pada kaidah syariah yang kokoh.\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:2;}i:2;a:10:{s:4:\"nama\";s:11:\"Budi Satoto\";s:8:\"kategori\";s:15:\"Dewan Komisaris\";s:7:\"jabatan\";s:29:\"Komisaris Utama (PLT Direksi)\";s:4:\"foto\";s:97:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/pengurus/komisaris-utama.png\";s:13:\"riwayat_karir\";s:212:\"Profesional perbankan dengan pengalaman luas di industri keuangan dan perbankan. Memiliki rekam jejak kepemimpinan strategis dalam pengawasan tata kelola perusahaan perbankan syariah yang sehat dan berkelanjutan.\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:64:\"Sertifikasi Komisaris BPR/BPRS (OJK), Manajemen Risiko Perbankan\";s:7:\"kutipan\";s:61:\"Tata kelola yang baik adalah kunci pertumbuhan berkelanjutan.\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:3;}i:3;a:10:{s:4:\"nama\";s:23:\"Rena Bangun Luhur S.PD.\";s:8:\"kategori\";s:15:\"Dewan Komisaris\";s:7:\"jabatan\";s:9:\"Komisaris\";s:4:\"foto\";s:102:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-23-at-11.44.45-AM.jpeg\";s:13:\"riwayat_karir\";s:191:\"Berpengalaman di bidang keuangan korporasi dan pengawasan kepatuhan. Berperan aktif dalam memastikan implementasi prinsip kehati-hatian dan kepatuhan regulasi OJK di lingkungan BPRS Wakalumi.\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:36:\"Sertifikasi Komisaris BPR/BPRS (OJK)\";s:7:\"kutipan\";s:53:\"Kepatuhan dan kehati-hatian adalah pilar kepercayaan.\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:4;}i:4;a:10:{s:4:\"nama\";s:14:\"Kiftiah Hindun\";s:8:\"kategori\";s:7:\"Direksi\";s:7:\"jabatan\";s:14:\"Direktur Utama\";s:4:\"foto\";s:117:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-23-at-11.45.08-AM-e1792482502383.jpeg\";s:13:\"riwayat_karir\";s:2:\"--\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:2:\"--\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:5;}i:5;a:10:{s:4:\"nama\";s:14:\"Lukman Nugroho\";s:8:\"kategori\";s:7:\"Direksi\";s:7:\"jabatan\";s:15:\"Direktur Bisnis\";s:4:\"foto\";s:114:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-09-22-at-2-removebackgrounds-ai-1.png\";s:13:\"riwayat_karir\";s:2:\"--\";s:10:\"pendidikan\";s:2:\"--\";s:11:\"sertifikasi\";s:2:\"--\";s:7:\"kutipan\";s:2:\"--\";s:6:\"status\";s:5:\"Aktif\";s:6:\"urutan\";i:6;}}','auto');
