INSERT INTO `wp_options` VALUES (631,'options_tabungan_list','a:4:{i:0;a:16:{s:4:\"nama\";s:32:\"Tawakal (Tabungan Umum Wakalumi)\";s:4:\"slug\";s:7:\"tawakal\";s:7:\"tagline\";s:22:\"Tabungan Umum Wakalumi\";s:5:\"badge\";s:15:\"Umum & Keluarga\";s:5:\"color\";s:4:\"teal\";s:4:\"icon\";s:7:\"tawakal\";s:9:\"penarikan\";s:0:\"\";s:4:\"akad\";s:20:\"Mudharabah Muthlaqah\";s:9:\"min_setor\";s:9:\"Rp 50.000\";s:11:\"biaya_admin\";s:28:\"Gratis / Bebas Biaya Bulanan\";s:4:\"desc\";s:142:\"Simpanan investasi dengan pola bagi hasil, dikelola dengan prinsip syariah. Solusi amanah untuk kemaslahatan simpanan perorangan dan keluarga.\";s:10:\"keunggulan\";s:246:\"Bebas biaya administrasi bulanan\r\nBagi hasil syariah kompetitif dibagikan setiap bulan\r\nSetoran awal sangat ringan dan terjangkau\r\nDapat disetor dan ditarik sewaktu-waktu pada jam operasional\r\nSimpanan aman dijamin Lembaga Penjamin Simpanan (LPS)\";s:6:\"syarat\";s:180:\"Mengisi dan menandatangani formulir pembukaan rekening\r\nMelampirkan fotokopi e-KTP / Paspor yang masih berlaku\r\nMelampirkan fotokopi NPWP (bila ada)\r\nSetoran awal minimal Rp 50.000\";s:7:\"wa_text\";s:109:\"Halo BSW, saya tertarik untuk membuka rekening Tabungan Tawakal. Mohon informasi prosedur dan persyaratannya.\";s:5:\"image\";s:84:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/tabungan-umum-wakalumi.jpeg\";s:6:\"urutan\";i:1;}i:1;a:16:{s:4:\"nama\";s:19:\"Tabungan Pendidikan\";s:4:\"slug\";s:10:\"pendidikan\";s:7:\"tagline\";s:27:\"Simpanan Masa Depan Pelajar\";s:5:\"badge\";s:19:\"Pelajar & Mahasiswa\";s:5:\"color\";s:4:\"blue\";s:4:\"icon\";s:10:\"pendidikan\";s:9:\"penarikan\";s:0:\"\";s:4:\"akad\";s:20:\"Mudharabah / Wadi`ah\";s:9:\"min_setor\";s:9:\"Rp 20.000\";s:11:\"biaya_admin\";s:28:\"Gratis / Bebas Biaya Bulanan\";s:4:\"desc\";s:157:\"Simpanan untuk para pelajar dengan pola bagi hasil, dikelola sesuai dengan prinsip syariah. Melatih kemandirian dan kebiasaan gemar menabung sejak usia dini.\";s:10:\"keunggulan\";s:273:\"Bebas biaya administrasi bulanan agar tabungan anak tidak terpotong\r\nBuku tabungan diterbitkan atas nama anak (pelajar)\r\nBagi hasil syariah yang berkah dan transparan\r\nPerencanaan biaya jenjang sekolah dan perguruan tinggi yang aman\r\nDijamin Lembaga Penjamin Simpanan (LPS)\";s:6:\"syarat\";s:242:\"Mengisi formulir pembukaan rekening oleh anak / orang tua wali\r\nFotokopi Kartu Identitas Anak (KIA) atau Akta Kelahiran\r\nFotokopi Kartu Pelajar (jika sudah ada)\r\nFotokopi e-KTP Orang Tua / Wali yang mendampingi\r\nSetoran awal minimal Rp 20.000\";s:7:\"wa_text\";s:131:\"Halo Bank Syariah Wakalumi, saya ingin membuka Tabungan Pendidikan untuk putra/putri saya. Mohon informasi syarat dan formulasinya.\";s:5:\"image\";s:81:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/tabungan-pendidikan.jpeg\";s:6:\"urutan\";i:2;}i:2;a:16:{s:4:\"nama\";s:23:\"Tabungan Haji dan Umroh\";s:4:\"slug\";s:10:\"haji-umroh\";s:7:\"tagline\";s:30:\"Langkah Niat Suci ke Baitullah\";s:5:\"badge\";s:16:\"Persiapan Ibadah\";s:5:\"color\";s:5:\"amber\";s:4:\"icon\";s:10:\"haji-umroh\";s:9:\"penarikan\";s:48:\"Fleksibel : Kapanpun pada jam operasional kantor\";s:4:\"akad\";s:20:\"Mudharabah Muthlaqah\";s:9:\"min_setor\";s:10:\"Rp 100.000\";s:11:\"biaya_admin\";s:28:\"Gratis / Bebas Biaya Bulanan\";s:4:\"desc\";s:131:\"Simpanan khusus bagi umat Islam yang akan menunaikan ibadah haji dan umroh dengan pola bagi hasil, dikelola dengan prinsip syariah.\";s:10:\"keunggulan\";s:343:\"Membantu percepatan pencapaian setoran awal porsi haji Kemenag (Rp 25 Juta) atau paket Umroh\r\nDana tersimpan aman dan terhindar dari pemakaian konsumtif sehari-hari\r\nBebas biaya administrasi bulanan\r\nBagi hasil bulanan diinvestasikan kembali untuk mempercepat keberangkatan\r\nPendampingan dan konsultasi berkala persiapan pendaftaran haji/umroh\";s:6:\"syarat\";s:228:\"Mengisi formulir pembukaan Tabungan Haji & Umroh\r\nMelampirkan fotokopi e-KTP yang masih berlaku\r\nMelampirkan fotokopi Kartu Keluarga (KK)\r\nPas foto 3x4 dan 4x6 latar putih (untuk persiapan porsi)\r\nSetoran awal minimal Rp 100.000\";s:7:\"wa_text\";s:126:\"Halo Bank Syariah Wakalumi, saya berencana membuka Tabungan Haji & Umroh. Mohon pendampingan informasi setoran dan porsi haji.\";s:5:\"image\";s:76:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/tab-haji-umroh.jpeg\";s:6:\"urutan\";i:3;}i:3;a:16:{s:4:\"nama\";s:37:\"Tabungan Ukhuwah (Tabungan Berhadiah)\";s:4:\"slug\";s:7:\"ukhuwah\";s:7:\"tagline\";s:36:\"Tabungan Berhadiah Berkah Tanpa Riba\";s:5:\"badge\";s:17:\"Program Berhadiah\";s:5:\"color\";s:4:\"cyan\";s:4:\"icon\";s:7:\"ukhuwah\";s:9:\"penarikan\";s:0:\"\";s:4:\"akad\";s:20:\"Mudharabah Muthlaqah\";s:9:\"min_setor\";s:10:\"Rp 100.000\";s:11:\"biaya_admin\";s:28:\"Gratis / Bebas Biaya Bulanan\";s:4:\"desc\";s:207:\"Simpanan investasi berjangka syariah yang memberikan kesempatan hadiah menarik (hadiah langsung atau poin undian berkah) bagi nasabah setia, dikelola murni dengan prinsip syariah yang adil dan menenteramkan.\";s:10:\"keunggulan\";s:294:\"Program apresiasi hadiah menarik tanpa melanggar prinsip syariah\r\nBagi hasil bulanan tetap menguntungkan dan bersaing\r\nBebas biaya administrasi bulanan\r\nNominal penempatan fleksibel dengan berbagai pilihan program hadiah\r\nSimpanan aman dijamin Lembaga Penjamin Simpanan (LPS) hingga Rp 2 Miliar\";s:6:\"syarat\";s:260:\"Mengisi formulir pembukaan Tabungan Ukhuwah Berhadiah\r\nMelampirkan fotokopi e-KTP yang masih berlaku\r\nMelampirkan fotokopi NPWP (bila ada)\r\nMenyetujui ketentuan periode penempatan dana program berhadiah\r\nSetoran awal minimal sesuai paket program hadiah pilihan\";s:7:\"wa_text\";s:141:\"Halo Bank Syariah Wakalumi, saya tertarik dengan program Tabungan Ukhuwah (Tabungan Berhadiah). Mohon info katalog hadiah dan persyaratannya.\";s:5:\"image\";s:78:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/Tabungan-ukhuwah.jpeg\";s:6:\"urutan\";i:4;}}','auto');
