INSERT INTO `wp_options` VALUES (874,'options_pembiayaan_calc_note','*Estimasi indikatif dengan formula perhitungan margin setara flat per tahun. Perhitungan riil disepakati saat akad resmi.','auto');
INSERT INTO `wp_options` VALUES (875,'options_pembiayaan_calc_btn_text','Ajukan Pembiayaan via WhatsApp','auto');
INSERT INTO `wp_options` VALUES (876,'options_pembiayaan_calc_presets','a:5:{i:0;a:4:{s:5:\"label\";s:24:\"Rp 10 Juta (Modal Mikro)\";s:7:\"nominal\";s:8:\"10000000\";s:5:\"tenor\";s:2:\"12\";s:4:\"prod\";s:24:\"Pembiayaan 1000 Pedagang\";}i:1;a:4:{s:5:\"label\";s:24:\"Rp 25 Jt (UMKM Pedagang)\";s:7:\"nominal\";s:8:\"25000000\";s:5:\"tenor\";s:2:\"24\";s:4:\"prod\";s:24:\"Pembiayaan 1000 Pedagang\";}i:2;a:4:{s:5:\"label\";s:22:\"Rp 35 Jt (Paket Umroh)\";s:7:\"nominal\";s:8:\"35000000\";s:5:\"tenor\";s:2:\"24\";s:4:\"prod\";s:54:\"Pembiayaan Multijasa (Ujrah Jasa / Umroh / Pendidikan)\";}i:3;a:4:{s:5:\"label\";s:26:\"Rp 50 Jt (Guru & Pengajar)\";s:7:\"nominal\";s:8:\"50000000\";s:5:\"tenor\";s:2:\"36\";s:4:\"prod\";s:20:\"Pembiayaan 1000 Guru\";}i:4;a:4:{s:5:\"label\";s:27:\"Rp 100 Jt (Investasi Usaha)\";s:7:\"nominal\";s:9:\"100000000\";s:5:\"tenor\";s:2:\"48\";s:4:\"prod\";s:35:\"Pembiayaan Al-Murabahah (Jual Beli)\";}}','auto');
INSERT INTO `wp_options` VALUES (877,'options_pembiayaan_faq_badge','Tanya Jawab (FAQ)','auto');
INSERT INTO `wp_options` VALUES (878,'options_pembiayaan_faq_title','Pertanyaan Seputar Pembiayaan Syariah','auto');
INSERT INTO `wp_options` VALUES (879,'options_pembiayaan_faq_sub','Pertanyaan umum nasabah seputar jaminan, waktu pencairan, sistem pelunasan, dan bebas denda riba.','auto');
INSERT INTO `wp_options` VALUES (880,'options_pembiayaan_faq_list','a:5:{i:0;a:2:{s:1:\"q\";s:83:\"Apa perbedaan mendasar pembiayaan syariah di BSW dengan pinjaman bank konvensional?\";s:1:\"a\";s:366:\"Pembiayaan di Bank Syariah Wakalumi berlandaskan akad-akad syariah yang sah dan diawasi oleh Dewan Pengawas Syariah (DPS & DSN-MUI). Kami tidak menerapkan sistem bunga pinjaman berbunga (riba). Keuntungan bank diperoleh dari margin jual beli yang pasti disepakati di awal (Murabahah), bagi hasil usaha riil (Mudharabah & Musyarakah), atau imbalan jasa sewa (Ijarah).\";}i:1;a:2:{s:1:\"q\";s:61:\"Berapa lama proses persetujuan dan pencairan dana pembiayaan?\";s:1:\"a\";s:316:\"Untuk program pembiayaan mikro seperti Pembiayaan 1000 Pedagang dan Pembiayaan 1000 Guru, proses persetujuan berkisar antara 1 hingga 3 hari kerja setelah berkas dan survei lapangan dinyatakan lengkap. Untuk pembiayaan komersial dan korporasi, proses menyesuaikan dengan analisis kelayakan usaha (feasibility study).\";}i:2;a:2:{s:1:\"q\";s:60:\"Apakah pembiayaan di BSW wajib menyertakan agunan / jaminan?\";s:1:\"a\";s:362:\"Secara umum, sebagai lembaga perbankan yang diawasi OJK, agunan diperlukan sebagai mitigasi risiko kepatuhan perbankan (seperti SHM, BPKB kendaraan, atau penjaminan payroll bagi guru). Namun untuk plafon usaha mikro tertentu atau program sosial Qardhul Hasan, skema jaminan dapat disesuaikan berdasarkan hasil musyawarah dan rekomendasi pengelola kelompok/pasar.\";}i:3;a:2:{s:1:\"q\";s:65:\"Apakah ada denda keterlambatan jika nasabah terlambat mengangsur?\";s:1:\"a\";s:322:\"Bank Syariah Wakalumi tidak memberlakukan denda keterlambatan yang dijadikan sebagai pendapatan bank (karena tergolong riba). Apabila ada biaya ta\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\'zir atas keterlambatan, dana tersebut wajib dialokasikan 100% untuk kas kebajikan sosial (dana kebajikan/infaq sosial dhuafa) dan bukan menjadi keuntungan bank.\";}i:4;a:2:{s:1:\"q\";s:92:\"Apakah nasabah dapat melunasi pembiayaan sebelum masa tenor berakhir (pelunasan dipercepat)?\";s:1:\"a\";s:251:\"Bisa. Nasabah berhak melakukan pelunasan dipercepat kapan saja tanpa dikenakan biaya penalti riba. Bahkan, sesuai fatwa DSN-MUI dan kebijakan bank, nasabah dapat diberikan potongan margin (muqassah) sebagai bentuk apresiasi atas kelancaran pembayaran.\";}}','auto');
INSERT INTO `wp_options` VALUES (881,'options_pembiayaan_alur_kicker','Proses Mudah & Cepat','auto');
INSERT INTO `wp_options` VALUES (882,'options_pembiayaan_alur_title','4 Tahapan Mudah Pengajuan Pembiayaan','auto');
INSERT INTO `wp_options` VALUES (883,'options_pembiayaan_alur_sub','Panduan tahapan transparan mulai dari konsultasi awal hingga dana pembiayaan cair ke rekening Anda.','auto');
INSERT INTO `wp_options` VALUES (884,'options_pembiayaan_step_1_title','1. Konsultasi & Pengisian Formulir','auto');
