INSERT INTO `wp_options` VALUES (1293,'options_pengumuman_list','a:3:{i:0;a:19:{s:2:\"id\";s:5:\"ann_1\";s:5:\"judul\";s:58:\"Perpindahan Kantor Pusat Operasional Bank Syariah Wakalumi\";s:8:\"kategori\";s:11:\"operasional\";s:7:\"urgensi\";s:7:\"penting\";s:7:\"tanggal\";s:10:\"2026-10-18\";s:11:\"nomor_surat\";s:26:\"No. 028/DIR-WKL/SE/IV/2026\";s:9:\"ringkasan\";s:77:\"Sehubungan dengan Perpindahan kantor pusat operasional bank syariah wakalumi.\";s:11:\"isi_lengkap\";s:779:\"Yth. Seluruh Nasabah dan Mitra BPRS Wakalumi,\r\n\r\nMenindaklanjuti Keputusan Bersama Pemerintah Republik Indonesia mengenai Hari Libur Nasional dan Cuti Bersama Hari Raya Idul Fitri 1447 H, dengan ini kami sampaikan penyesuaian jadwal operasional kantor:\r\n\r\n1. Layanan Tatap Muka Kantor Operasional TUTUP sementara mulai tanggal cuti bersama.\r\n2. Seluruh jaringan kantor kas dan kantor cabang akan BUKA KEMBALI melayani nasabah secara normal pada hari kerja berikutnya pukul 08.00 WIB.\r\n3. Layanan transaksi perbankan tetap dapat diakses melalui saluran mitra dan komunikasi WhatsApp resmi bank kami.\r\n\r\nDemikian pengumuman ini kami sampaikan. Segenap Direksi, Dewan Pengawas Syariah, dan Karyawan BPRS Wakalumi mengucapkan Selamat Hari Raya Idul Fitri, Mohon Maaf Lahir dan Batin.\";s:6:\"gambar\";s:101:\"http://wakalumibprscoid.local/wp-content/uploads/2026/10/WhatsApp-Image-2026-10-10-at-5.22.06-AM.jpeg\";s:8:\"file_pdf\";s:81:\"http://wakalumibprscoid.local/wp-content/uploads/2026/09/PUBLIKASI-MARET-2025.pdf\";s:9:\"file_size\";s:20:\"PDF Resmi • 1.2 MB\";s:11:\"link_active\";s:1:\"1\";s:9:\"link_text\";s:11:\"link berita\";s:8:\"link_url\";s:86:\"http://wakalumibprscoid.local/berita/bank-syariah-wakalumi-resmikan-kantor-pusat-baru/\";s:11:\"link_target\";s:6:\"_blank\";s:8:\"is_toast\";s:1:\"1\";s:8:\"is_popup\";s:1:\"1\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:1;}i:1;a:19:{s:2:\"id\";s:5:\"ann_2\";s:5:\"judul\";s:71:\"Himbauan Keamanan: Waspada Modus Penipuan Mengatasnamakan BPRS Wakalumi\";s:8:\"kategori\";s:8:\"keamanan\";s:7:\"urgensi\";s:7:\"penting\";s:7:\"tanggal\";s:10:\"2026-10-13\";s:11:\"nomor_surat\";s:27:\"No. 015/DIR-WKL/HMB/II/2026\";s:9:\"ringkasan\";s:189:\"Waspada terhadap modus penipuan berkedok hadiah, undian, atau permintaan data pribadi (OTP, PIN, Password). BPRS Wakalumi tidak pernah meminta biaya transfer ke rekening pribadi perorangan.\";s:11:\"isi_lengkap\";s:799:\"Yth. Nasabah Setia Bank Syariah Wakalumi,\r\n\r\nKami menghimbau kepada seluruh nasabah dan masyarakat agar selalu meningkatkan kewaspadaan terhadap maraknya penipuan daring yang mengatasnamakan PT BPRS Wakalumi.\r\n\r\nMohon perhatikan hal-hal krusial berikut:\r\n1. BPRS Wakalumi TIDAK PERNAH meminta kode OTP, PIN, Password, maupun data rahasia lainnya kepada nasabah melalui media apapun.\r\n2. Seluruh transaksi pembiayaan dan pembukaan rekening hanya diproses melalui rekening resmi perseroan (PT BPRS Wakalumi), BUKAN atas nama perorangan atau staf pribadi.\r\n3. Kanal informasi dan layanan resmi kami hanya dapat diakses melalui nomor WhatsApp resmi Customer Service yang tertera di website ini.\r\n\r\nBila Anda menerima pesan mencurigakan, segera konfirmasi dan laporkan ke layanan pengaduan konsumen kami.\";s:6:\"gambar\";s:0:\"\";s:8:\"file_pdf\";s:0:\"\";s:9:\"file_size\";s:20:\"PDF Resmi • 850 KB\";s:11:\"link_active\";s:1:\"0\";s:9:\"link_text\";s:0:\"\";s:8:\"link_url\";s:0:\"\";s:11:\"link_target\";s:6:\"_blank\";s:8:\"is_toast\";s:1:\"1\";s:8:\"is_popup\";s:1:\"1\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:2;}i:2;a:19:{s:2:\"id\";s:5:\"ann_3\";s:5:\"judul\";s:71:\"Pengumuman Pelaksanaan Lelang Eksekusi Hak Tanggungan Agunan Pembiayaan\";s:8:\"kategori\";s:6:\"lelang\";s:7:\"urgensi\";s:6:\"normal\";s:7:\"tanggal\";s:10:\"2026-10-04\";s:11:\"nomor_surat\";s:25:\"No. 008/LELANG-WKL/I/2026\";s:9:\"ringkasan\";s:191:\"Pengumuman pelaksanaan lelang eksekusi hak tanggungan atas agunan pembiayaan bekerjasama dengan Kantor Pelayanan Kekayaan Negara dan Lelang (KPKNL) secara terbuka melalui portal resmi lelang.\";s:11:\"isi_lengkap\";s:799:\"Berdasarkan Pasal 6 Undang-Undang Hak Tanggungan No. 4 Tahun 1996, PT BPRS Wakalumi dengan perantaraan Kantor Pelayanan Kekayaan Negara dan Lelang (KPKNL) akan melaksanakan Lelang Eksekusi Hak Tanggungan atas objek jaminan yang telah memenuhi syarat lelang perbankan.\r\n\r\nSyarat dan Ketentuan Lelang:\r\n1. Penawaran lelang dilakukan secara tertulis tanpa kehadiran peserta lelang melalui aplikasi resmi Lelang Indonesia (portal KPKNL).\r\n2. Peserta lelang wajib menyetorkan uang jaminan lelang sesuai nominal pengumuman sebelum batas waktu penutupan.\r\n3. Objek lelang dijual dalam kondisi apa adanya (as is) dengan segala kekurangan dan konsekuensi hukumnya.\r\n\r\nInformasi lengkap mengenai rincian batas tanah, sertifikat hak milik, dan nilai limit lelang dapat dilihat pada lampiran surat edaran resmi.\";s:6:\"gambar\";s:0:\"\";s:8:\"file_pdf\";s:0:\"\";s:9:\"file_size\";s:20:\"PDF Resmi • 2.1 MB\";s:11:\"link_active\";s:1:\"0\";s:9:\"link_text\";s:0:\"\";s:8:\"link_url\";s:0:\"\";s:11:\"link_target\";s:6:\"_blank\";s:8:\"is_toast\";s:1:\"1\";s:8:\"is_popup\";s:1:\"0\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:3;}}','auto');
