INSERT INTO `wp_options` VALUES (1304,'options_pengurus_ojk_notice_desc','Sesuai dengan POJK tentang Penilaian Kemampuan dan Kepatutan bagi Pihak Utama Lembaga Jasa Keuangan, posisi Direktur BPRS Wakalumi saat ini tengah menjalani tahapan proses perizinan resmi di Otoritas Jasa Keuangan (OJK). Seluruh aktivitas operasional dan pelayanan perbankan kepada nasabah tetap berjalan dengan pengawasan penuh dari Dewan Komisaris dan Dewan Pengawas Syariah (DPS).','auto');
