INSERT INTO `wp_options` VALUES (1347,'options_lelang_title','Info Lelang Agunan & Penjualan Aset','auto');
INSERT INTO `wp_options` VALUES (1348,'options_lelang_desc','Portal resmi publikasi lelang eksekusi Hak Tanggungan dan penjualan Agunan Yang Diambil Alih (AYDA) PT BPRS Wakalumi. Seluruh proses diselenggarakan secara amanah, transparan, serta mematuhi regulasi POJK dan prinsip syariah DSN-MUI.','auto');
INSERT INTO `wp_options` VALUES (1349,'options_lelang_card_badge','Berdasarkan Ketentuan Syariah & Regulasi','auto');
INSERT INTO `wp_options` VALUES (1350,'options_lelang_card_title','Mekanisme Adil & Bebas Riba','auto');
INSERT INTO `wp_options` VALUES (1351,'options_lelang_card_desc','Penjualan melalui portal negara KPKNL (lelang.go.id) atau penjualan damai atas persetujuan debitur. Kelebihan hasil lelang wajib dikembalikan kepada nasabah pemilik agunan sesuai Fatwa DSN-MUI.','auto');
