INSERT INTO `wp_options` VALUES (1354,'options_lelang_pilar_subtitle','Sesuai Fatwa DSN-MUI No. 47/DSN-MUI/II/2005 dan regulasi Otoritas Jasa Keuangan (POJK):','auto');
INSERT INTO `wp_options` VALUES (1355,'options_lelang_pilar_1_title','1. Kelebihan Hasil Lelang Hak Nasabah','auto');
INSERT INTO `wp_options` VALUES (1356,'options_lelang_pilar_1_desc','Seluruh kelebihan nilai penjualan di atas sisa kewajiban piutang nasabah wajib dikembalikan ke nasabah pemilik agunan.','auto');
INSERT INTO `wp_options` VALUES (1357,'options_lelang_pilar_2_title','2. Transparan & Bebas Gharar','auto');
INSERT INTO `wp_options` VALUES (1358,'options_lelang_pilar_2_desc','Nilai limit lelang, kondisi fisik, dan status legalitas sertifikat/BPKB diumumkan secara jujur dan terbuka.','auto');
INSERT INTO `wp_options` VALUES (1359,'options_lelang_pilar_3_title','3. Saluran Sah (KPKNL / Sukarela)','auto');
INSERT INTO `wp_options` VALUES (1360,'options_lelang_pilar_3_desc','Dilaksanakan lewat KPKNL (lelang.go.id) atau penjualan damai atas persetujuan debitur demi kemaslahatan bersama.','auto');
INSERT INTO `wp_options` VALUES (1361,'options_lelang_panduan_show','1','auto');
INSERT INTO `wp_options` VALUES (1362,'options_lelang_panduan_title','Panduan Ringkas: Memahami Mekanisme Lelang Agunan & AYDA Syariah BPRS Wakalumi','auto');
INSERT INTO `wp_options` VALUES (1363,'options_lelang_panduan_1_title','1. Penjualan Sukarela vs. Lelang KPKNL','auto');
INSERT INTO `wp_options` VALUES (1364,'options_lelang_panduan_1_desc','Aset berstatus Tersedia dapat langsung dinegosiasikan secara damai. Sedangkan aset Akan Dilelang dilaksanakan melalui sistem penawaran lelang resmi negara via portal lelang.go.id.','auto');
INSERT INTO `wp_options` VALUES (1365,'options_lelang_panduan_2_title','2. Hak Pengembalian Lebih Debitur','auto');
INSERT INTO `wp_options` VALUES (1366,'options_lelang_panduan_2_desc','Sesuai Fatwa DSN-MUI, bank dilarang mengambil untung zalim atas penderitaan nasabah. Apabila hasil penjualan melebihi total sisa piutang pokok + biaya sah, selisih wajib diserahkan kepada nasabah.','auto');
INSERT INTO `wp_options` VALUES (1367,'options_lelang_panduan_3_title','3. Didukung Pembiayaan KPR Syariah','auto');
INSERT INTO `wp_options` VALUES (1368,'options_lelang_panduan_3_desc','Khusus properti rumah dan ruko siap huni, peminat dapat mengajukan fasilitas pembiayaan cicilan syariah (Murabahah/Musyarakah Mutanaqisah) kepada BPRS Wakalumi dengan DP yang disepakati.','auto');
INSERT INTO `wp_options` VALUES (1369,'options_lelang_cta_badge','Layanan Remedial & Likuidasi Aset','auto');
INSERT INTO `wp_options` VALUES (1370,'options_lelang_cta_title','Ingin Mengajukan Penawaran','auto');
INSERT INTO `wp_options` VALUES (1371,'options_lelang_cta_desc','Tim Remedial BPRS Wakalumi siap mendampingi Anda untuk survei lokasi fisik, pengecekan berkas sertifikat di kantor bank, dan konsultasi skema KPR Syariah.','auto');
