INSERT INTO `wp_options` VALUES (1377,'options_lelang_list','a:5:{i:0;a:22:{s:2:\"id\";s:8:\"lelang_1\";s:4:\"kode\";s:13:\"AYDA-2026-001\";s:5:\"judul\";s:46:\"Rumah Tinggal 2 Lantai Minimalis Modern & Asri\";s:8:\"kategori\";s:5:\"rumah\";s:6:\"status\";s:8:\"tersedia\";s:11:\"harga_limit\";s:14:\"Rp 680.000.000\";s:11:\"nilai_pasar\";s:14:\"Rp 920.000.000\";s:12:\"uang_jaminan\";s:14:\"Rp 136.000.000\";s:9:\"legalitas\";s:36:\"SHM (Sertifikat Hak Milik) No. 04821\";s:10:\"luas_tanah\";s:7:\"135 m²\";s:13:\"luas_bangunan\";s:7:\"160 m²\";s:6:\"lokasi\";s:73:\"Cluster Pondok Indah Pamulang, Jl. Surya Kencana No. B-12, Pamulang Barat\";s:4:\"kota\";s:17:\"Tangerang Selatan\";s:14:\"tanggal_lelang\";s:40:\"Terbuka (Penjualan Sukarela / Siap Huni)\";s:13:\"tempat_lelang\";s:48:\"Kantor Pusat PT BPRS Wakalumi & On-Site Property\";s:10:\"foto_utama\";s:93:\"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80\";s:11:\"galeri_foto\";s:283:\"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1600573472592-401b489a3cdc?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:359:\"Hunian 2 lantai siap huni dengan struktur kokoh di lingkungan tenang dan bebas banjir.\r\n\r\nDilengkapi 3 Kamar Tidur, 2 Kamar Mandi, Ruang Tamu luas, Dapur bersih, Carport untuk 2 mobil, Daya Listrik 2200 VA, dan Air Sumur Bor Jetpump jernih. Akses jalan aspal lebar 2 mobil, hanya 10 menit ke Gerbang Tol Pamulang (Tol Serpong-Cinere) dan Universitas Pamulang.\";s:9:\"tata_cara\";s:263:\"Aset ini berstatus Penjualan Sukarela (AYDA) atas persetujuan debitur. Peminat dapat langsung menjadwalkan survei fisik bersama tim remedial BPRS Wakalumi dan dapat dibeli secara tunai maupun diajukan fasilitas Pembiayaan Kepemilikan Rumah (KPR) Syariah Wakalumi.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:1;}i:1;a:22:{s:2:\"id\";s:8:\"lelang_2\";s:4:\"kode\";s:13:\"AYDA-2026-002\";s:5:\"judul\";s:54:\"Ruko Komersial 3 Lantai Strategis Pusat Bisnis Ciputat\";s:8:\"kategori\";s:4:\"ruko\";s:6:\"status\";s:13:\"akan_dilelang\";s:11:\"harga_limit\";s:16:\"Rp 1.450.000.000\";s:11:\"nilai_pasar\";s:16:\"Rp 1.950.000.000\";s:12:\"uang_jaminan\";s:14:\"Rp 290.000.000\";s:9:\"legalitas\";s:45:\"SHGB (Sertifikat Hak Guna Bangunan) No. 01275\";s:10:\"luas_tanah\";s:21:\"96 m² (4.5 x 21.3 m)\";s:13:\"luas_bangunan\";s:7:\"240 m²\";s:6:\"lokasi\";s:69:\"Kompleks Ruko Ciputat Bisnis Center, Jl. Dewi Sartika No. 18, Ciputat\";s:4:\"kota\";s:17:\"Tangerang Selatan\";s:14:\"tanggal_lelang\";s:34:\"26 November 2026 (Pukul 10.30 WIB)\";s:13:\"tempat_lelang\";s:45:\"KPKNL Tangerang I / Portal Resmi lelang.go.id\";s:10:\"foto_utama\";s:93:\"https://images.unsplash.com/photo-1541888946425-d0fbb1861593?auto=format&fit=crop&w=1200&q=80\";s:11:\"galeri_foto\";s:188:\"https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:340:\"Ruko komersial 3 lantai berada di tepi jalan raya utama Ciputat dengan lalu lintas ramai 24 jam.\r\n\r\nSangat cocok untuk kantor cabang perbankan/fintech, klinik kesehatan, kantor notaris/hukum, restoran, maupun minimarket. Dilengkapi fasilitas area parkir paving luas, rolling door elektrik, kamar mandi di setiap lantai, dan listrik 5500 VA.\";s:9:\"tata_cara\";s:288:\"Lelang eksekusi Hak Tanggungan dilaksanakan resmi secara closed bidding melalui portal negara lelang.go.id yang dikelola KPKNL Tangerang I. Penyetoran uang jaminan lelang dilakukan melalui Virtual Account (VA) yang diterbitkan lelang.go.id paling lambat 1 hari sebelum pelaksanaan lelang.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:2;}i:2;a:22:{s:2:\"id\";s:8:\"lelang_3\";s:4:\"kode\";s:13:\"AYDA-2026-003\";s:5:\"judul\";s:60:\"Tanah Kavling Siap Bangun Kawasan Eksklusif Bintaro Sektor 9\";s:8:\"kategori\";s:5:\"tanah\";s:6:\"status\";s:8:\"tersedia\";s:11:\"harga_limit\";s:14:\"Rp 950.000.000\";s:11:\"nilai_pasar\";s:16:\"Rp 1.300.000.000\";s:12:\"uang_jaminan\";s:14:\"Rp 190.000.000\";s:9:\"legalitas\";s:36:\"SHM (Sertifikat Hak Milik) No. 08194\";s:10:\"luas_tanah\";s:19:\"260 m² (13 x 20 m)\";s:13:\"luas_bangunan\";s:1:\"-\";s:6:\"lokasi\";s:78:\"Jl. Kasuari Raya, Kel. Pondok Pucung, Kec. Pondok Aren (Bintaro Jaya Sektor 9)\";s:4:\"kota\";s:5:\"Bogor\";s:14:\"tanggal_lelang\";s:34:\"Tersedia (Penjualan Langsung Bank)\";s:13:\"tempat_lelang\";s:29:\"Kantor Pusat PT BPRS Wakalumi\";s:10:\"foto_utama\";s:93:\"https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1200&q=80\";s:11:\"galeri_foto\";s:188:\"https://images.unsplash.com/photo-1524813686514-a57563d77d66?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1464226184884-fa280b87c399?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:385:\"Tanah kavling matang siap bangun dengan bentuk persegi panjang ideal di area Bintaro Sektor 9 yang sangat berkembang pesat.\r\n\r\nPosisi hook, tanah padat bukan urukan rawa, dikelilingi perumahan elit menengah ke atas. Jaringan listrik bawah tanah, air bersih PDAM, dan keamanan security 24 jam. Lokasi hanya 5 menit dari Bintaro Xchange Mall, Stasiun Jurangmangu, dan RS Premier Bintaro.\";s:9:\"tata_cara\";s:212:\"Peminat dapat langsung mengajukan surat penawaran harga (SPH) resmi ke Bagian Remedial & AYDA BPRS Wakalumi. Tersedia skema pembayaran cicilan berjangka (Akad Murabahah) dengan persetujuan Komite Pembiayaan Bank.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:3;}i:3;a:22:{s:2:\"id\";s:8:\"lelang_4\";s:4:\"kode\";s:13:\"AYDA-2026-004\";s:5:\"judul\";s:58:\"Toyota All New Kijang Innova Venturer 2.4 AT Diesel (2021)\";s:8:\"kategori\";s:9:\"kendaraan\";s:6:\"status\";s:13:\"akan_dilelang\";s:11:\"harga_limit\";s:14:\"Rp 325.000.000\";s:11:\"nilai_pasar\";s:14:\"Rp 395.000.000\";s:12:\"uang_jaminan\";s:13:\"Rp 65.000.000\";s:9:\"legalitas\";s:58:\"BPKB Asli + STNK Aktif + Faktur Pembelian (Plat B Tangsel)\";s:10:\"luas_tanah\";s:1:\"-\";s:13:\"luas_bangunan\";s:1:\"-\";s:6:\"lokasi\";s:86:\"Pool Kendaraan Operasional BPRS Wakalumi, Jl. RE Martadinata No. 15, Cipayung, Ciputat\";s:4:\"kota\";s:17:\"Tangerang Selatan\";s:14:\"tanggal_lelang\";s:33:\"3 Desember 2026 (Pukul 09.00 WIB)\";s:13:\"tempat_lelang\";s:46:\"KPKNL Tangerang II / Portal Resmi lelang.go.id\";s:10:\"foto_utama\";s:90:\"https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=1200&q=80\";s:11:\"galeri_foto\";s:185:\"https://images.unsplash.com/photo-1552519507-da3b142c6e3d?auto=format&fit=crop&w=1200&q=80\r\nhttps://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:440:\"Kendaraan roda empat tipe premium MPV keluarga Toyota Kijang Innova Venturer 2.4 Diesel Automatic transmisi tahun perakitan 2021.\r\n\r\nWarna Hitam Metalik, odometer rendah (48.000 km), servis rutin bengkel resmi Auto2000. Interior kulit captain seat terawat mulus, AC digital double blower dingin, ban tebal 85%, mesin diesel bertenaga & kering tanpa rembesan oli. Dokumen kepemilikan BPKB, STNK asli, kunci cadangan, dan buku manual lengkap.\";s:9:\"tata_cara\";s:227:\"Pengecekan fisik unit (Open House / Test Drive) dibuka setiap hari kerja pukul 09.00 - 15.00 WIB di Kantor Pusat BPRS Wakalumi dengan konfirmasi terlebih dahulu ke PIC Lelang. Penawaran dilakukan secara online via lelang.go.id.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:4;}i:4;a:22:{s:2:\"id\";s:8:\"lelang_5\";s:4:\"kode\";s:13:\"AYDA-2026-005\";s:5:\"judul\";s:52:\"Rumah Tinggal 1 Lantai Tipe Hook Asri Sawangan Depok\";s:8:\"kategori\";s:5:\"rumah\";s:6:\"status\";s:7:\"terjual\";s:11:\"harga_limit\";s:14:\"Rp 395.000.000\";s:11:\"nilai_pasar\";s:14:\"Rp 510.000.000\";s:12:\"uang_jaminan\";s:13:\"Rp 79.000.000\";s:9:\"legalitas\";s:36:\"SHM (Sertifikat Hak Milik) No. 02931\";s:10:\"luas_tanah\";s:7:\"112 m²\";s:13:\"luas_bangunan\";s:6:\"65 m²\";s:6:\"lokasi\";s:48:\"Perumahan Grand Sawangan Asri Blok D-5, Sawangan\";s:4:\"kota\";s:5:\"Depok\";s:14:\"tanggal_lelang\";s:35:\"Selesai Terlelang (14 Oktober 2026)\";s:13:\"tempat_lelang\";s:11:\"KPKNL Bogor\";s:10:\"foto_utama\";s:93:\"https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=1200&q=80\";s:11:\"galeri_foto\";s:93:\"https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1200&q=80\";s:9:\"deskripsi\";s:224:\"Hunian 1 lantai asri dengan kelebihan tanah hook di Sawangan. 2 Kamar Tidur, 1 Kamar Mandi, Ruang Tamu, dan Taman samping asri. Selesai terlelang secara sukses dan akta risalah lelang telah diserahkan kepada pemenang lelang.\";s:9:\"tata_cara\";s:145:\"Aset ini telah berstatus Terjual / Selesai Likuidasi. Kelebihan dana hasil lelang telah diserahkan kepada pihak debitur sesuai ketentuan syariah.\";s:16:\"kepatuhan_custom\";s:0:\"\";s:10:\"wa_contact\";s:0:\"\";s:6:\"urutan\";i:5;}}','auto');
