INSERT INTO `wp_options` VALUES (1384,'options_lelang_pill_3','Legalitas Terverifikasi (SHM/BPKB)','auto');
INSERT INTO `wp_options` VALUES (1385,'options_lelang_pilar_items','a:3:{i:0;a:2:{s:5:\"title\";s:37:\"1. Kelebihan Hasil Lelang Hak Nasabah\";s:4:\"desc\";s:118:\"Seluruh kelebihan nilai penjualan di atas sisa kewajiban piutang nasabah wajib dikembalikan ke nasabah pemilik agunan.\";}i:1;a:2:{s:5:\"title\";s:28:\"2. Transparan & Bebas Gharar\";s:4:\"desc\";s:107:\"Nilai limit lelang, kondisi fisik, dan status legalitas sertifikat/BPKB diumumkan secara jujur dan terbuka.\";}i:2;a:2:{s:5:\"title\";s:33:\"3. Saluran Sah (KPKNL / Sukarela)\";s:4:\"desc\";s:112:\"Dilaksanakan lewat KPKNL (lelang.go.id) atau penjualan damai atas persetujuan debitur demi kemaslahatan bersama.\";}}','auto');
INSERT INTO `wp_options` VALUES (1390,'options_lelang_status_tersedia_prosedur_title','Prosedur Pembelian Sukarela & Survei Fisik','auto');
INSERT INTO `wp_options` VALUES (1391,'options_lelang_status_tersedia_prosedur_desc','Aset ini berstatus Penjualan Sukarela (AYDA) atas persetujuan debitur. Peminat dapat langsung menjadwalkan survei fisik bersama tim remedial BPRS Wakalumi dan dapat dibeli secara tunai maupun diajukan fasilitas Pembiayaan Kepemilikan Rumah (KPR) Syariah Wakalumi.','auto');
INSERT INTO `wp_options` VALUES (1392,'options_lelang_status_tersedia_kepatuhan_title','Kepatuhan Syariah & Hukum (Penjualan Damai Sukarela):','auto');
INSERT INTO `wp_options` VALUES (1393,'options_lelang_status_tersedia_kepatuhan_desc','Penjualan diselenggarakan secara damai berdasarkan persetujuan tertulis pihak debitur dengan prinsip tolong-menolong (ta\\\\\\\\\\\\\\\'awun) dan bebas riba. Sesuai Fatwa DSN-MUI No. 47, seluruh kelebihan hasil penjualan setelah pelunasan sisa kewajiban piutang wajib diserahkan kembali kepada nasabah pemilik agunan.','auto');
INSERT INTO `wp_options` VALUES (1394,'options_lelang_status_akan_dilelang_prosedur_title','Prosedur Keikutsertaan Lelang & Survei Fisik','auto');
INSERT INTO `wp_options` VALUES (1395,'options_lelang_status_akan_dilelang_prosedur_desc','Lelang eksekusi Hak Tanggungan dilaksanakan resmi secara closed/open bidding melalui portal negara lelang.go.id yang dikelola KPKNL. Penyetoran uang jaminan lelang dilakukan melalui Virtual Account (VA) yang diterbitkan lelang.go.id paling lambat 1 hari kalender sebelum pelaksanaan lelang. Peminat wajib melakukan survei fisik (*as is where is*) dan verifikasi berkas sebelum menyetor uang jaminan.','auto');
INSERT INTO `wp_options` VALUES (1396,'options_lelang_status_akan_dilelang_kepatuhan_title','Kepatuhan Hukum & Fatwa DSN-MUI (Eksekusi Hak Tanggungan):','auto');
INSERT INTO `wp_options` VALUES (1397,'options_lelang_status_akan_dilelang_kepatuhan_desc','Lelang dieksekusi berdasarkan Pasal 6 UU Hak Tanggungan No. 4/1996 dan diawasi Pejabat Lelang Negara KPKNL. Berdasarkan Fatwa DSN-MUI No. 47/DSN-MUI/II/2005, bank hanya berhak mengambil pelunasan pokok piutang dan biaya eksekusi riil, sedangkan seluruh kelebihan dana hasil lelang wajib dikembalikan utuh kepada debitur.','auto');
INSERT INTO `wp_options` VALUES (1398,'options_lelang_status_terjual_prosedur_title','Informasi Status Likuidasi Aset','auto');
INSERT INTO `wp_options` VALUES (1399,'options_lelang_status_terjual_prosedur_desc','Aset ini telah berstatus Terjual / Selesai Likuidasi. Risalah lelang resmi atau akta jual beli telah diserahkan secara sah kepada pemenang lelang/pembeli. Halaman publikasi ini tidak lagi menerima pendaftaran penawaran baru untuk aset ini.','auto');
INSERT INTO `wp_options` VALUES (1400,'options_lelang_status_terjual_kepatuhan_title','Akuntabilitas & Penyelesaian Transaksi Syariah:','auto');
INSERT INTO `wp_options` VALUES (1401,'options_lelang_status_terjual_kepatuhan_desc','Proses likuidasi agunan telah berkekuatan hukum tetap (inkracht). Seluruh hak debitur atas kelebihan dana hasil likuidasi telah disalurkan kembali kepada pihak debitur secara amanah dan akuntabel sesuai ketentuan syariah.','auto');
INSERT INTO `wp_options` VALUES (1407,'kategori_berita_children','a:0:{}','auto');
INSERT INTO `wp_options` VALUES (1424,'options_galeri_badge','Dokumentasi & Galeri Visual','auto');
INSERT INTO `wp_options` VALUES (1425,'options_galeri_title','Galeri Dokumentasi BSW','auto');
INSERT INTO `wp_options` VALUES (1426,'options_galeri_desc','Koleksi rekam jejak, dinamika aktivitas perbankan syariah, program sosial CSR, serta momen bersejarah Bank Syariah Wakalumi bersama nasabah, mitra usaha, dan masyarakat.','auto');
INSERT INTO `wp_options` VALUES (1427,'options_galeri_card_badge','Galeri & Rekam Jejak','auto');
INSERT INTO `wp_options` VALUES (1428,'options_galeri_card_title','Dokumentasi Visual','auto');
INSERT INTO `wp_options` VALUES (1429,'options_galeri_card_desc','Setiap visual mencerminkan dedikasi Bank Syariah Wakalumi dalam melayani umat, memberdayakan perekonomian syariah, dan menjaga integritas tata kelola yang amanah.','auto');
INSERT INTO `wp_options` VALUES (1430,'options_galeri_albums','a:6:{i:0;a:11:{s:2:\"id\";s:5:\"alb_1\";s:5:\"judul\";s:59:\"Program CSR: Penyaluran Paket Sembako & Santunan Anak Yatim\";s:8:\"kategori\";s:3:\"csr\";s:7:\"tanggal\";s:10:\"2026-09-28\";s:6:\"lokasi\";s:47:\"Kantor Pusat BSW & Yayasan Yatim Dhuafa Mandiri\";s:9:\"ringkasan\";s:151:\"Penyaluran bingkisan sembako berkah, santunan pendidikan, serta buka puasa bersama anak yatim dalam momentum keberkahan syiar sosial perbankan syariah.\";s:11:\"cover_image\";s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/about-photo.jpg\";s:9:\"foto_list\";a:2:{i:0;s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/about-photo.jpg\";i:1;s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/video-thumb.jpg\";}s:9:\"video_url\";s:0:\"\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:1;}i:1;a:11:{s:2:\"id\";s:5:\"alb_2\";s:5:\"judul\";s:64:\"Workshop Literasi Perbankan Syariah & Akselerasi Pembiayaan UMKM\";s:8:\"kategori\";s:7:\"edukasi\";s:7:\"tanggal\";s:10:\"2026-09-03\";s:6:\"lokasi\";s:41:\"Auditorium Pusat UMKM Kreatif & Kemitraan\";s:9:\"ringkasan\";s:156:\"Pelatihan manajemen keuangan halal, pembukuan digital kas mikro, dan pembiayaan modal kerja syariah dengan akad Murabahah & Mudharabah bagi 100 pelaku UMKM.\";s:11:\"cover_image\";s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/video-thumb.jpg\";s:9:\"foto_list\";a:2:{i:0;s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/video-thumb.jpg\";i:1;s:84:\"http://wakalumibprscoid.local/wp-content/themes/assets/../assets/img/about-photo.jpg\";}s:9:\"video_url\";s:0:\"\";s:6:\"status\";s:5:\"aktif\";s:6:\"urutan\";i:2;}i:2;a:11:{s:2:\"id\";s:5:\"alb_3\";s:5:\"judul\";s:66:\"Rapat Umum Pemegang Saham (RUPS) Tahunan & Paparan Kinerja Positif\";s:8:\"kategori\";s:9:\"corporate\";s:7:\"tanggal\";s:10:\"2026-07-30\";s:6:\"lokasi\";s:51:\"Ballroom Utama