INSERT INTO `wp_posts` VALUES (95,1,'2026-10-18 18:49:07','2026-10-18 11:13:26','Bank Syariah Wakalumi (BSW) resmi membuka babak baru dengan peresmian kantor pusat di kawasan Rempoa, Ciputat Timur, Tangerang Selatan. Acara tasyakuran yang digelar pada 25 September 2026 ini menjadi momentum penting dalam perjalanan panjang bank syariah yang telah hadir sejak 1989.\r\n\r\nPeresmian gedung baru dihadiri oleh jajaran Otoritas Jasa Keuangan (OJK), pelaku usaha, tokoh masyarakat, serta mitra strategis. Kehadiran mereka menegaskan posisi BPRS Wakalumi sebagai lembaga keuangan syariah yang berkomitmen mendukung pertumbuhan ekonomi daerah dan pemberdayaan UMKM.\r\n\r\nLangkah relokasi ini diharapkan mampu memperkuat kapabilitas operasional, memperluas jangkauan layanan, serta menghadirkan pengalaman perbankan syariah yang lebih modern dan terintegrasi. Filosofi nilai <strong>#WAQF (Wisdom, Accountability, Quality, Foresight)</strong> kembali ditegaskan sebagai landasan pertumbuhan, menjadikan kantor pusat baru bukan sekadar fasilitas fisik, melainkan pusat inklusi keuangan syariah bagi masyarakat dan wirausahawan lokal.\r\n\r\nSumber berita utama: <a href=\"https://campusnet.news/perkuat-ekosistem-keuangan-syariah-bank-syariah-wakalumi-resmikan-kantor-pusat-baru-di-rempoa-ciputat\">CampusNet</a>','Bank Syariah Wakalumi Resmikan Kantor Pusat Baru','Bank Syariah Wakalumi (BPRS Wakalumi) resmi membuka babak baru dengan peresmian kantor pusat di kawasan Rempoa, Ciputat Timur, Tangerang Selatan. Acara tasyakuran yang digelar pada 25 September 2026 ini menjadi momentum penting dalam perjalanan panjang bank syariah yang telah hadir sejak 1989.','publish','closed','closed','','bank-syariah-wakalumi-resmikan-kantor-pusat-baru','','','2026-10-18 18:49:07','2026-10-18 11:49:07','',0,'http://wakalumibprscoid.local/berita/bank-syariah-wakalumi-resmikan-kantor-pusat-baru/',0,'berita','',0);
