INSERT INTO `wp_posts` VALUES (104,1,'2026-10-18 18:48:36','2026-10-18 11:48:36','Bank Pembiayaan Rakyat Syariah (BPRS) Wakalumi fokus bekerja sama dengan<a href=\"https://republika.co.id/tag/lembaga-pendidikan\"> lembaga pendidikan </a>Islam. Upaya ini dinilai berpotensi tinggi karena mampu menghimpun dana.\r\n<div></div>\r\n<p class=\"b2\">Dengan kesederhanaan yang dimiliki, BPRS Wakalumi terus mengedukasi masyarakat akan dunia perbankan syariah. BPRS tersebut menggarap segmen bisnis yang mengarah pada <em>linkage program</em>.</p>\r\n\r\n<div id=\"bn_acv2yxxtly9\" class=\"recreative\"></div>\r\n<p class=\"b2\">Direktur Utama BPRS Wakalumi, Silvia mengatakan per Oktober 2013, aset. BPRS Wakalumi mencapai Rp 15,5 miliar dengan target hingga akhir tahun. Target aset hingga akhir tahun Rp 16,3 miliar.</p>','BPRS Wakalumi Fokus Kerja Sama dengan Lembaga Pendidikan Islam ‪','Bank Pembiayaan Rakyat Syariah (BPRS) Wakalumi fokus bekerja sama dengan lembaga pendidikan Islam.','publish','closed','closed','','bprs-wakalumi-fokus-kerja-sama-dengan-lembaga-pendidikan-islam','','','2026-10-18 18:48:36','2026-10-18 11:48:36','',0,'http://wakalumibprscoid.local/berita/bprs-wakalumi-fokus-kerja-sama-dengan-lembaga-pendidikan-islam/',0,'berita','',0);
INSERT INTO `wp_posts` VALUES (105,1,'2026-10-18 18:49:07','2026-10-18 11:49:07','Bank Syariah Wakalumi (BSW) resmi membuka babak baru dengan peresmian kantor pusat di kawasan Rempoa, Ciputat Timur, Tangerang Selatan. Acara tasyakuran yang digelar pada 25 September 2026 ini menjadi momentum penting dalam perjalanan panjang bank syariah yang telah hadir sejak 1989.\r\n\r\nPeresmian gedung baru dihadiri oleh jajaran Otoritas Jasa Keuangan (OJK), pelaku usaha, tokoh masyarakat, serta mitra strategis. Kehadiran mereka menegaskan posisi BPRS Wakalumi sebagai lembaga keuangan syariah yang berkomitmen mendukung pertumbuhan ekonomi daerah dan pemberdayaan UMKM.\r\n\r\nLangkah relokasi ini diharapkan mampu memperkuat kapabilitas operasional, memperluas jangkauan layanan, serta menghadirkan pengalaman perbankan syariah yang lebih modern dan terintegrasi. Filosofi nilai <strong>#WAQF (Wisdom, Accountability, Quality, Foresight)</strong> kembali ditegaskan sebagai landasan pertumbuhan, menjadikan kantor pusat baru bukan sekadar fasilitas fisik, melainkan pusat inklusi keuangan syariah bagi masyarakat dan wirausahawan lokal.\r\n\r\nSumber berita utama: <a href=\"https://campusnet.news/perkuat-ekosistem-keuangan-syariah-bank-syariah-wakalumi-resmikan-kantor-pusat-baru-di-rempoa-ciputat\">CampusNet</a>','Bank Syariah Wakalumi Resmikan Kantor Pusat Baru','Bank Syariah Wakalumi (BPRS Wakalumi) resmi membuka babak baru dengan peresmian kantor pusat di kawasan Rempoa, Ciputat Timur, Tangerang Selatan. Acara tasyakuran yang digelar pada 25 September 2026 ini menjadi momentum penting dalam perjalanan panjang bank syariah yang telah hadir sejak 1989.','inherit','closed','closed','','95-revision-v1','','','2026-10-18 18:49:07','2026-10-18 11:49:07','',95,'http://wakalumibprscoid.local/?p=105',0,'revision','',0);
